class StreamManager:
    def reconnect(self, session):
        # The RTSP callback can run after StreamContext has been destroyed.
        self._context.callback()

class RtspClient:
    def __init__(self, stream_manager):
        self._manager = stream_manager
        self._pending = None

    def on_connection_lost(self, session):
        # Logs 'reconnect callback scheduled', then runs on_reconnect later.
        # Does not hold the StreamContext, so teardown can destroy it first.
        context = self._manager._context
        self._pending = lambda: self.on_reconnect(session, context)

    def on_reconnect(self, session, context):
        self._manager.reconnect(session)

class StreamContext:
    def __init__(self, session_id):
        self.session_id = session_id
        self._holds = 0
        self._destroyed = False

    def hold(self):
        if self._destroyed:
            raise RuntimeError("StreamContext destroyed")
        self._holds += 1

    def release(self):
        if self._holds:
            self._holds -= 1

    def destroy(self):
        # Does not cancel a reconnect that was already scheduled.
        self._destroyed = True

    def callback(self):
        if self._destroyed:
            raise RuntimeError("StreamContext destroyed")
        return "reconnected"
